From 381c7afbe60a0e6d53e8cc1bca2de920574b3383 Mon Sep 17 00:00:00 2001
From: Michael Meffie <mmeffie@sinenomine.net>
Date: Wed, 21 Jan 2015 14:58:35 -0500
Subject: [PATCH] bozo: do not exit when the client config already exists

The bosserver creates symlinks for the client CSDB and ThisCell config
files during initialization.  Avoid exiting if the client CSDB or
ThisCell configuration already exists, otherwise the bosserver cannot be
restarted with bos restart.

This fixes an error introduced with commit
720363fa9bf7cfbebdc485104b74ca6bac1895f6, Fix unchecked return values.

Change-Id: Ie6ecf126d1ed663f161c26da2a8c4d568369d99d
Reviewed-on: http://gerrit.openafs.org/11684
Tested-by: BuildBot <buildbot@rampaginggeek.com>
Reviewed-by: Perry Ruiter <pruiter@sinenomine.net>
Reviewed-by: Benjamin Kaduk <kaduk@mit.edu>

diff --git a/src/bozo/bosserver.c b/src/bozo/bosserver.c
index ca85c229e..fa568076e 100644
--- a/src/bozo/bosserver.c
+++ b/src/bozo/bosserver.c
@@ -283,11 +283,17 @@ CreateDirs(const char *coredir)
 	return errno;

     if (symlink(AFSDIR_SERVER_THISCELL_FILEPATH,
-	    AFSDIR_CLIENT_THISCELL_FILEPATH))
-	return errno;
+	    AFSDIR_CLIENT_THISCELL_FILEPATH)) {
+	if (errno != EEXIST) {
+	    return errno;
+	}
+    }
     if (symlink(AFSDIR_SERVER_CELLSERVDB_FILEPATH,
-	    AFSDIR_CLIENT_CELLSERVDB_FILEPATH))
-	return errno;
+	    AFSDIR_CLIENT_CELLSERVDB_FILEPATH)) {
+	if (errno != EEXIST) {
+	    return errno;
+	}
+    }
 #endif /* AFS_NT40_ENV */
     if (coredir) {
 	if (MakeDir(coredir))
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `bosserver` exiting when it attempted to create symlinks for the client CSDB and ThisCell configuration files during initialization, even if those symlinks already existed. This behavior was introduced by a previous commit that changed how return values were handled, leading to an unintentional exit of the server when encountering an existing file error (EEXIST).

        Commit message:
        bozo: do not exit when the client config already exists

The bosserver creates symlinks for the client CSDB and ThisCell config
files during initialization.  Avoid exiting if the client CSDB or
ThisCell configuration already exists, otherwise the bosserver cannot be
restarted with bos restart.

This fixes an error introduced with commit
720363fa9bf7cfbebdc485104b74ca6bac1895f6, Fix unchecked return values.

Change-Id: Ie6ecf126d1ed663f161c26da2a8c4d568369d99d
Reviewed-on: http://gerrit.openafs.org/11684
Tested-by: BuildBot <buildbot@rampaginggeek.com>
Reviewed-by: Perry Ruiter <pruiter@sinenomine.net>
Reviewed-by: Benjamin Kaduk <kaduk@mit.edu>  

        Patch:
         /* create all the bozo dirs */
 static int
 CreateDirs(const char *coredir)
 {
     if ((!strncmp
 	 (AFSDIR_USR_DIRPATH, AFSDIR_CLIENT_ETC_DIRPATH,
 	  strlen(AFSDIR_USR_DIRPATH)))
 	||
 	(!strncmp
 	 (AFSDIR_USR_DIRPATH, AFSDIR_SERVER_BIN_DIRPATH,
 	  strlen(AFSDIR_USR_DIRPATH)))) {
 	if (MakeDir(AFSDIR_USR_DIRPATH))
 	    return errno;
     }
     if (!strncmp
 	(AFSDIR_SERVER_AFS_DIRPATH, AFSDIR_SERVER_BIN_DIRPATH,
 	 strlen(AFSDIR_SERVER_AFS_DIRPATH))) {
 	if (MakeDir(AFSDIR_SERVER_AFS_DIRPATH))
 	    return errno;
     }
     if (MakeDir(AFSDIR_SERVER_BIN_DIRPATH))
 	return errno;
     if (MakeDir(AFSDIR_SERVER_ETC_DIRPATH))
 	return errno;
     if (MakeDir(AFSDIR_SERVER_LOCAL_DIRPATH))
 	return errno;
     if (MakeDir(AFSDIR_SERVER_DB_DIRPATH))
 	return errno;
     if (MakeDir(AFSDIR_SERVER_LOGS_DIRPATH))
 	return errno;
 #ifndef AFS_NT40_ENV
     if (!strncmp
 	(AFSDIR_CLIENT_VICE_DIRPATH, AFSDIR_CLIENT_ETC_DIRPATH,
 	 strlen(AFSDIR_CLIENT_VICE_DIRPATH))) {
 	if (MakeDir(AFSDIR_CLIENT_VICE_DIRPATH))
 	    return errno;
     }
     if (MakeDir(AFSDIR_CLIENT_ETC_DIRPATH))
 	return errno;

     if (symlink(AFSDIR_SERVER_THISCELL_FILEPATH,
-	    AFSDIR_CLIENT_THISCELL_FILEPATH))
-	return errno;
+	    AFSDIR_CLIENT_THISCELL_FILEPATH)) {
+	if (errno != EEXIST) {
+	    return errno;
+	}
+    }
     if (symlink(AFSDIR_SERVER_CELLSERVDB_FILEPATH,
-	    AFSDIR_CLIENT_CELLSERVDB_FILEPATH))
-	return errno;
+	    AFSDIR_CLIENT_CELLSERVDB_FILEPATH)) {
+	if (errno != EEXIST) {
+	    return errno;
+	}
+    }
 #endif /* AFS_NT40_ENV */
     if (coredir) {
 	if (MakeDir(coredir))
 	    return errno;
     }
     return 0;
 }



